import "core-js/modules/es.array.push.js";
import AdminToggleDark from './dashboard/AdminToggleDark.vue';
import { IconCameraUp, IconPhoto, IconSettings, IconUserCog } from '@tabler/icons-vue';
export default {
  name: 'DashboardTabs',
  props: {
    activeTab: {
      type: String,
      default: 'home'
    }
  },
  components: {
    AdminToggleDark,
    IconCameraUp
  },
  computed: {
    navItems() {
      return [{
        key: 'home',
        route: '/',
        icon: IconCameraUp,
        label: '主页'
      }, {
        key: 'gallery',
        route: '/dashboard',
        icon: IconPhoto,
        label: '图库'
      }, {
        key: 'users',
        route: '/customerConfig',
        icon: IconUserCog,
        label: '用户'
      }, {
        key: 'settings',
        route: '/systemConfig',
        icon: IconSettings,
        label: '设置'
      }];
    }
  },
  methods: {
    handleTabClick(route) {
      if (this.$route.path === route) return;
      this.$router.push(route);
    }
  }
};